import base64, json
# Opaque cursor: client sees a string, server sees (sort, tiebreaker, version).
# Never expose raw offsets or allow client-constructed SQL fragments.
def encode_cursor(created_at: str, last_id: int, v: int = 1) -> str:
    payload = json.dumps({"v": v, "ts": created_at, "id": last_id}).encode()
    return base64.urlsafe_b64encode(payload).decode()

def decode_cursor(token: str) -> tuple:
    data = json.loads(base64.urlsafe_b64decode(token.encode()).decode())
    assert data["v"] == 1  # bump version when sort changes; reject old cursors
    return data["ts"], data["id"]
